with s0 as (with s1 as (select s2_result.* from unnest(@pi0::jsonb[]) as i0, lateral (with recursive s2_seed(root_id) as not materialized (select n1.id as root_id from node n1 where (n1.id = ((i0 ->> E'graph_id'))::int8)), s2(root_id, next_id, depth, satisfied, is_cycle, path) as (select s2_seed.root_id, s2_seed.root_id, 0, false, false, array []::int8[] from s2_seed union select e0.end_id, e0.start_id, 1, false, e0.end_id = e0.start_id, array [e0.id] from s2_seed join edge e0 on e0.end_id = s2_seed.root_id where e0.kind_id = any (array [101, 134]::int2[]) union select s2.root_id, e0.start_id, s2.depth + 1, false, false, e0.id || s2.path from s2 join lateral (select e0.id, e0.start_id, e0.end_id, e0.kind_id, e0.properties from edge e0 where e0.end_id = s2.next_id and e0.id != all (s2.path) and e0.kind_id = any (array [101, 134]::int2[]) offset 0) e0 on true where not s2.is_cycle and s2.depth > 0) select i0 as i0, (n0.id, n0.kind_ids, n0.properties)::nodecomposite as n0, (n1.id, n1.kind_ids, n1.properties)::nodecomposite as n1 from s2 join lateral (select n1.id, n1.kind_ids, n1.properties from node n1 where n1.id = s2.root_id offset 0) n1 on true join lateral (select n0.id, n0.kind_ids, n0.properties from node n0 where n0.id = s2.next_id offset 0) n0 on true) s2_result) select distinct s1.n0 as n0 from s1), s3 as (with s4 as (select s0.n0 as n0, row_number() over () as i1 from s0), s5 as (select s6_result.* from s4, lateral (with recursive s6_seed(root_id) as not materialized (select distinct (s4.n0).id as root_id), s6(root_id, next_id, depth, satisfied, is_cycle, path) as (select e1.start_id, e1.end_id, 1, false, e1.start_id = e1.end_id, array [e1.id] from s6_seed join edge e1 on e1.start_id = s6_seed.root_id where e1.kind_id = any (array [101, 134]::int2[]) union all select s6.root_id, e1.end_id, s6.depth + 1, false, false, s6.path || e1.id from s6 join lateral (select e1.id, e1.start_id, e1.end_id, e1.kind_id, e1.properties from edge e1 where e1.start_id = s6.next_id and e1.id != all (s6.path) and e1.kind_id = any (array [101, 134]::int2[]) offset 0) e1 on true where not s6.is_cycle) select (select coalesce(array_agg((_edge.id, _edge.start_id, _edge.end_id, _edge.kind_id, _edge.properties)::edgecomposite order by _path.ordinality), array []::edgecomposite[]) from unnest(s6.path) with ordinality as _path(id, ordinality) join edge _edge on _edge.id = _path.id) as e1, s6.path as ep1, s4.i1 as i1, (n0.id, n0.kind_ids, n0.properties)::nodecomposite as n0, (n2.id, n2.kind_ids, n2.properties)::nodecomposite as n2 from s6 join lateral (select n0.id, n0.kind_ids, n0.properties from node n0 where n0.id = s6.root_id offset 0) n0 on true join lateral (select n2.id, n2.kind_ids, n2.properties from node n2 where n2.id = s6.next_id offset 0) n2 on true where (n2.id = n0.id) and (s4.n0).id = s6.root_id) s6_result), s7 as (select s4.i1 as i1, s4.n0 as n0, s5.e1 as e1, s5.ep1 as ep1, s5.n2 as n2 from s4 left outer join s5 on (s4.n0 is not distinct from s5.n0) and (s4.i1 is not distinct from s5.i1)) select s7.n0 as n0, 1 / (1 - count(distinct s7.n2)::int8) as i2 from s7 group by n0), s8 as (select s3.i2 as i2, s3.n0 as n0, row_number() over () as i3 from s3), s9 as (select s10_result.* from s8, lateral (with recursive s10_seed(root_id) as not materialized (select distinct (s8.n0).id as root_id), s10(root_id, next_id, depth, satisfied, is_cycle, path) as (select e2.end_id, e2.start_id, 1, false, e2.end_id = e2.start_id, array [e2.id] from s10_seed join edge e2 on e2.end_id = s10_seed.root_id where e2.kind_id = any (array [101, 134]::int2[]) union all select s10.root_id, e2.start_id, s10.depth + 1, false, false, e2.id || s10.path from s10 join lateral (select e2.id, e2.start_id, e2.end_id, e2.kind_id, e2.properties from edge e2 where e2.end_id = s10.next_id and e2.id != all (s10.path) and e2.kind_id = any (array [101, 134]::int2[]) offset 0) e2 on true where not s10.is_cycle) select (select coalesce(array_agg((_edge.id, _edge.start_id, _edge.end